from backend.identity.actor import ActorContext, AuthorizationError, ClaimsMappingError, UserRole
from backend.identity.claims import ClaimsToActorMapper
from backend.identity.rbac import BusinessAction, assert_action_allowed, is_action_allowed


def test_claim_mapper_builds_actor_context_from_valid_oidc_claims() -> None:
    mapper = ClaimsToActorMapper()
    claims = {
        "sub": "oidc|user-123",
        "user_id": "13b57789-d523-47ad-85fd-b3ed9b7bc0c5",
        "preferred_username": "mario.rossi",
        "name": "Mario Rossi",
        "email": "mario.rossi@example.it",
        "roles": ["operator"],
        "amr": ["pwd", "otp"],
    }

    actor = mapper.from_claims(claims, request_id="req-oidc-1")

    assert actor.user_id == UUID("13b57789-d523-47ad-85fd-b3ed9b7bc0c5")
    assert actor.display_name == "Mario Rossi"
    assert actor.role == UserRole.operator
    assert actor.idp_subject == "oidc|user-123"
    assert actor.email == "mario.rossi@example.it"
    assert actor.request_id == "req-oidc-1"
    assert actor.mfa_authenticated is True
    assert actor.mfa_methods == ("pwd", "otp")
    assert actor.claims_source == "oidc"


def test_claim_mapper_builds_actor_context_from_valid_saml_mapped_claims() -> None:
    mapper = ClaimsToActorMapper()
    claims = {
        "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier": "saml-subject-9000",
        "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name": "Amministratore Demo",
        "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress": "admin@example.it",
        "groups": ["team:zen-admin"],
        "mfa": True,
    }

    actor = mapper.from_claims(claims, request_id="req-saml-1")

    assert actor.display_name == "Amministratore Demo"
    assert actor.role == UserRole.admin
    assert actor.idp_subject == "saml-subject-9000"
    assert actor.email == "admin@example.it"
    assert actor.request_id == "req-saml-1"
    assert actor.mfa_authenticated is True
    assert actor.claims_source == "saml"
    assert isinstance(actor.user_id, UUID)


def test_claim_mapper_derives_stable_user_id_and_preserves_acr_based_mfa_signal() -> None:
    mapper = ClaimsToActorMapper()
    claims = {
        "sub": "oidc|derived-user",
        "name": "Derived User",
        "roles": ["tenant/operator"],
        "acr": "urn:mace:incommon:iap:multi-factor",
    }

    actor = mapper.from_claims(claims, request_id="req-derived-1")

    assert actor.user_id == uuid5(mapper.subject_namespace, "oidc|derived-user")
    assert actor.role == UserRole.operator
    assert actor.mfa_authenticated is True
    assert actor.mfa_methods == ()


def test_claim_mapper_rejects_missing_supported_role_claim() -> None:
    mapper = ClaimsToActorMapper()
    claims = {
        "sub": "oidc|user-without-role",
        "name": "No Role User",
        "email": "norole@example.it",
    }

    with pytest.raises(ClaimsMappingError, match="missing supported role claim"):
        mapper.from_claims(claims, request_id="req-no-role")


def test_claim_mapper_rejects_invalid_explicit_user_id() -> None:
    mapper = ClaimsToActorMapper()
    claims = {
        "sub": "oidc|bad-user-id",
        "user_id": "not-a-uuid",
        "roles": ["operator"],
    }

    with pytest.raises(ClaimsMappingError, match="invalid user_id claim"):
        mapper.from_claims(claims, request_id="req-bad-user-id")


def test_rbac_policy_denies_auditor_for_state_changing_validation() -> None:
    actor = ActorContext(
        user_id=UUID("f877542e-98fe-4ff8-a266-3ab9ccae8c8b"),
        display_name="Utente Auditor",
        role=UserRole.auditor,
        idp_subject="oidc|auditor-1",
        request_id="req-auditor-1",
    )

    assert is_action_allowed(actor.role, BusinessAction.search_archive) is True
    assert is_action_allowed(actor.role, BusinessAction.validate_document) is False

    with pytest.raises(AuthorizationError):
        assert_action_allowed(actor, BusinessAction.validate_document)


def test_rbac_policy_allows_admin_for_state_changing_actions() -> None:
    actor = ActorContext(
        user_id=UUID("13b57789-d523-47ad-85fd-b3ed9b7bc0c5"),
        display_name="Admin User",
        role=UserRole.admin,
        idp_subject="oidc|admin-1",
        request_id="req-admin-1",
    )

    assert is_action_allowed(actor.role, BusinessAction.upload) is True
    assert is_action_allowed(actor.role, BusinessAction.validate_document) is True
    assert is_action_allowed(actor.role, BusinessAction.export_metadata) is True

    assert_action_allowed(actor, BusinessAction.state_change)
