from __future__ import annotations

from dataclasses import dataclass, field
from enum import Enum
from typing import Any
from uuid import UUID

_REQUIRED_ROLE_VALUES = frozenset({"operator", "admin", "auditor"})

try:
    from backend.shared.models.enums import UserRole as CanonicalUserRole
except (ImportError, ModuleNotFoundError):  # pragma: no cover - isolated staging fallback only
    class CanonicalUserRole(str, Enum):
        operator = "operator"
        admin = "admin"
        auditor = "auditor"
else:
    _canonical_role_values = {
        str(getattr(member, "value", member))
        for member in CanonicalUserRole
    }
    _missing_role_values = _REQUIRED_ROLE_VALUES - _canonical_role_values
    if _missing_role_values:
        missing = ", ".join(sorted(_missing_role_values))
        raise RuntimeError(
            "backend.shared.models.enums.UserRole is missing required role values: "
            f"{missing}"
        )


UserRole = CanonicalUserRole


@dataclass(frozen=True, slots=True)
class ActorContext:
    user_id: UUID
    display_name: str
    role: UserRole
    idp_subject: str
    request_id: str
    email: str | None = None
    mfa_authenticated: bool | None = None
    mfa_methods: tuple[str, ...] = field(default_factory=tuple)
    claims_source: str = "unknown"


class AuthenticationError(Exception):
    """Authentication failed before an actor context could be built."""


class ClaimsMappingError(AuthenticationError):
    """Claims were present but insufficient or malformed for actor mapping."""


class AuthorizationError(Exception):
    """A mapped actor is authenticated but not allowed to perform an action."""

    def __init__(
        self,
        message: str,
        *,
        request_id: str,
        required_roles: tuple[str, ...] = (),
    ) -> None:
        super().__init__(message)
        self.request_id = request_id
        self.required_roles = required_roles


def role_value(role: UserRole | str) -> str:
    if isinstance(role, str):
        return role
    return str(getattr(role, "value", role))


def normalize_role(role: UserRole | str) -> UserRole:
    try:
        return UserRole(role_value(role))
    except ValueError as exc:
