from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Iterable, Mapping
from uuid import UUID, uuid5

from backend.identity.actor import ActorContext, ClaimsMappingError, UserRole, normalize_role


SAML_NAME_ID_KEYS = (
    "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/nameidentifier",
    "nameidentifier",
    "name_id",
)
SAML_EMAIL_KEYS = (
    "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/emailaddress",
    "emailaddress",
)
SAML_DISPLAY_NAME_KEYS = (
    "http://schemas.xmlsoap.org/ws/2005/05/identity/claims/name",
    "displayname",
)
SAML_ROLE_KEYS = (
    "http://schemas.microsoft.com/ws/2008/06/identity/claims/role",
    "role",
    "roles",
    "groups",
)

OIDC_SUBJECT_KEYS = ("sub", "subject")
USER_ID_KEYS = ("user_id", "custom:user_id", "app_user_id")
EMAIL_KEYS = ("email",) + SAML_EMAIL_KEYS
DISPLAY_NAME_KEYS = ("name", "display_name", "preferred_username", "username") + SAML_DISPLAY_NAME_KEYS
ROLE_KEYS = ("role", "roles", "groups", "cognito:groups", "app_roles") + SAML_ROLE_KEYS

MFA_METHOD_TOKENS = {"mfa", "otp", "totp", "sms", "webauthn", "fido", "hardware_key"}
ROLE_PRIORITY = {"admin": 0, "operator": 1, "auditor": 2}


@dataclass(slots=True, frozen=True)
class ClaimsToActorMapper:
    subject_namespace: UUID = UUID("6cb79b5d-2f83-4bb2-acaf-56cbda8f4c72")

    def from_claims(
        self,
        claims: Mapping[str, Any],
        *,
        request_id: str,
        claims_source: str | None = None,
    ) -> ActorContext:
        if not claims:
            raise ClaimsMappingError("missing identity claims")

        source = claims_source or self._infer_claims_source(claims)
        idp_subject = self._require_first_str(claims, OIDC_SUBJECT_KEYS + SAML_NAME_ID_KEYS, "idp subject")
        role = self._resolve_role(claims)
        user_id = self._resolve_user_id(claims, idp_subject)
        email = self._first_str(claims, EMAIL_KEYS)
        display_name = self._resolve_display_name(claims, fallback=email or idp_subject)
        mfa_methods = self._extract_mfa_methods(claims)
        mfa_authenticated = self._extract_mfa_authenticated(claims, mfa_methods)

        return ActorContext(
            user_id=user_id,
            display_name=display_name,
            role=role,
            idp_subject=idp_subject,
            request_id=request_id,
            email=email,
            mfa_authenticated=mfa_authenticated,
            mfa_methods=mfa_methods,
            claims_source=source,
        )

    def _infer_claims_source(self, claims: Mapping[str, Any]) -> str:
        if any(str(key).startswith("http://schemas.") for key in claims):
            return "saml"
        return "oidc"

    def _resolve_user_id(self, claims: Mapping[str, Any], idp_subject: str) -> UUID:
        raw_user_id = self._first_str(claims, USER_ID_KEYS)
        if raw_user_id:
            try:
                return UUID(raw_user_id)
            except ValueError as exc:
                raise ClaimsMappingError("invalid user_id claim; expected UUID") from exc
        return uuid5(self.subject_namespace, idp_subject)

    def _resolve_display_name(self, claims: Mapping[str, Any], *, fallback: str) -> str:
        display_name = self._first_str(claims, DISPLAY_NAME_KEYS)
        if display_name:
            return display_name
        given_name = self._first_str(claims, ("given_name",))
        family_name = self._first_str(claims, ("family_name",))
        joined = " ".join(part for part in (given_name, family_name) if part)
        return joined or fallback

    def _resolve_role(self, claims: Mapping[str, Any]) -> UserRole:
        candidates: list[UserRole] = []

        for key in ROLE_KEYS:
            value = claims.get(key)
            for candidate in self._iter_role_candidates(value):
                resolved = self._candidate_to_role(candidate)
                if resolved is not None:
                    candidates.append(resolved)

        if not candidates:
            raise ClaimsMappingError("missing supported role claim")

        return min(candidates, key=lambda role: ROLE_PRIORITY[str(role.value)])

    def _candidate_to_role(self, candidate: str) -> UserRole | None:
        normalized = candidate.strip().lower()
        if not normalized:
            return None

        tokens = {normalized}
        for delimiter in (":", "/", "-", "_", " ", ",", ";", "|"):
            parts = tuple(part for part in normalized.split(delimiter) if part)
            tokens.update(parts)

        for role_name in ("operator", "admin", "auditor"):
            if role_name in tokens:
                return normalize_role(role_name)
        return None

    def _iter_role_candidates(self, value: Any) -> Iterable[str]:
        if value is None:
            return ()
        if isinstance(value, str):
            return (value,)
        if isinstance(value, (list, tuple, set, frozenset)):
            return tuple(str(item) for item in value)
        return (str(value),)

    def _extract_mfa_methods(self, claims: Mapping[str, Any]) -> tuple[str, ...]:
        methods: list[str] = []
        raw_amr = claims.get("amr")

        if isinstance(raw_amr, str):
            methods.extend(part.strip().lower() for part in raw_amr.split() if part.strip())
        elif isinstance(raw_amr, (list, tuple, set, frozenset)):
            methods.extend(str(item).strip().lower() for item in raw_amr if str(item).strip())

        return tuple(dict.fromkeys(methods))

    def _extract_mfa_authenticated(
        self,
        claims: Mapping[str, Any],
        mfa_methods: tuple[str, ...],
    ) -> bool | None:
        raw_explicit = self._coerce_optional_bool(claims.get("mfa"))
        if raw_explicit is not None:
            return raw_explicit

        raw_enabled = self._coerce_optional_bool(claims.get("mfa_enabled"))
        if raw_enabled is not None:
            return raw_enabled

        if any(method in MFA_METHOD_TOKENS for method in mfa_methods):
            return True

        acr = claims.get("acr")
        if isinstance(acr, str) and "mfa" in acr.lower():
            return True

        if mfa_methods:
            return False
        return None

    def _coerce_optional_bool(self, value: Any) -> bool | None:
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            normalized = value.strip().lower()
            if normalized in {"true", "1", "yes"}:
                return True
            if normalized in {"false", "0", "no"}:
                return False
        return None

    def _require_first_str(
        self,
        claims: Mapping[str, Any],
        keys: Iterable[str],
        field_name: str,
    ) -> str:
        value = self._first_str(claims, keys)
        if not value:
            raise ClaimsMappingError(f"missing {field_name} claim")
        return value

    def _first_str(self, claims: Mapping[str, Any], keys: Iterable[str]) -> str | None:
        for key in keys:
            raw = claims.get(key)
            if isinstance(raw, str) and raw.strip():
                return raw.strip()
        return None
