from __future__ import annotations

import base64
import binascii
import hashlib
import hmac
import json
import time
from typing import Any, Callable, Iterable, Mapping, Protocol
from uuid import uuid4

from fastapi import HTTPException, Request, status

from backend.identity.actor import (
    ActorContext,
    AuthenticationError,
    AuthorizationError,
    ClaimsMappingError,
    UserRole,
    normalize_role,
)
from backend.identity.claims import ClaimsToActorMapper


class IdentityProvider(Protocol):
    def authenticate(self, request: Request) -> Mapping[str, Any]:
        """Return verified identity claims or raise AuthenticationError."""


class HmacJwtIdentityProvider:
    """Local-dev compatible OIDC-style bearer JWT verifier using HS256."""

    def __init__(
        self,
        *,
        shared_secret: str,
        expected_issuer: str | None = None,
        expected_audience: str | None = None,
        clock_skew_seconds: int = 30,
    ) -> None:
        if not shared_secret:
            raise ValueError("shared_secret is required")
        self.shared_secret = shared_secret.encode("utf-8")
        self.expected_issuer = expected_issuer
        self.expected_audience = expected_audience
        self.clock_skew_seconds = clock_skew_seconds

    def authenticate(self, request: Request) -> Mapping[str, Any]:
        token = _extract_bearer_token(request)
        try:
            return _decode_hs256_jwt(
                token,
                shared_secret=self.shared_secret,
                expected_issuer=self.expected_issuer,
                expected_audience=self.expected_audience,
                clock_skew_seconds=self.clock_skew_seconds,
            )
        except (ValueError, TypeError, json.JSONDecodeError) as exc:
            raise AuthenticationError("invalid bearer token") from exc


class TrustedHeaderIdentityProvider:
    """
    Production-close seam for AWS/on-prem ingress that already verified identity
    and forwards claims as base64url encoded JSON.
    """

    def __init__(self, *, claims_header: str = "x-auth-claims") -> None:
        normalized = claims_header.strip().lower()
        if not normalized:
            raise ValueError("claims_header is required")
        self.claims_header = normalized

    def authenticate(self, request: Request) -> Mapping[str, Any]:
        encoded_claims = request.headers.get(self.claims_header)
        if not encoded_claims:
            raise AuthenticationError(f"missing trusted claims header: {self.claims_header}")

        try:
            decoded = _b64url_decode(encoded_claims)
            claims = json.loads(decoded.decode("utf-8"))
        except (ValueError, TypeError, json.JSONDecodeError) as exc:
            raise AuthenticationError("invalid trusted claims header payload") from exc

        if not isinstance(claims, dict):
            raise AuthenticationError("trusted claims payload must decode to an object")
        return claims


def build_current_actor_dependency(
    identity_provider: IdentityProvider,
    *,
    mapper: ClaimsToActorMapper | None = None,
    allowed_roles: Iterable[UserRole | str] | None = None,
) -> Callable[[Request], ActorContext]:
    normalized_roles = tuple(normalize_role(role) for role in (allowed_roles or ()))
    claims_mapper = mapper or ClaimsToActorMapper()

    async def dependency(request: Request) -> ActorContext:
        request_id = _resolve_request_id(request)
        request.state.correlation_id = request_id

        try:
            claims = identity_provider.authenticate(request)
            actor = claims_mapper.from_claims(claims, request_id=request_id)
        except (AuthenticationError, ClaimsMappingError) as exc:
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail={
                    "code": "authentication_failed",
                    "message": str(exc),
                    "correlation_id": request_id,
                },
                headers={"WWW-Authenticate": "Bearer"},
            ) from exc

        request.state.actor = actor

        if normalized_roles and actor.role not in normalized_roles:
            exc = AuthorizationError(
                f"role {actor.role.value} is not allowed for this endpoint",
                request_id=request_id,
                required_roles=tuple(role.value for role in normalized_roles),
            )
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail={
                    "code": "authorization_failed",
                    "message": str(exc),
                    "required_roles": list(exc.required_roles),
                    "correlation_id": request_id,
                },
            ) from exc

        return actor

    return dependency


def _resolve_request_id(request: Request) -> str:
    return (
        request.headers.get("x-request-id")
        or request.headers.get("x-correlation-id")
        or getattr(request.state, "correlation_id", None)
        or str(uuid4())
    )


def _extract_bearer_token(request: Request) -> str:
    authorization = request.headers.get("authorization")
    if not authorization:
        raise AuthenticationError("missing Authorization header")

    scheme, _, token = authorization.partition(" ")
    if scheme.lower() != "bearer" or not token:
        raise AuthenticationError("expected Bearer token")
    return token.strip()


def _decode_hs256_jwt(
    token: str,
    *,
    shared_secret: bytes,
    expected_issuer: str | None,
    expected_audience: str | None,
    clock_skew_seconds: int,
) -> Mapping[str, Any]:
    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("invalid JWT structure")

    header_segment, payload_segment, signature_segment = parts
    header_raw = json.loads(_b64url_decode(header_segment).decode("utf-8"))
    payload_raw = json.loads(_b64url_decode(payload_segment).decode("utf-8"))

    if not isinstance(header_raw, dict):
        raise ValueError("JWT header must be a JSON object")
    if not isinstance(payload_raw, dict):
        raise ValueError("JWT payload must be a JSON object")

    if header_raw.get("alg") != "HS256":
        raise ValueError("unsupported JWT algorithm")

    signing_input = f"{header_segment}.{payload_segment}".encode("ascii")
    expected_signature = hmac.new(shared_secret, signing_input, hashlib.sha256).digest()
    if not hmac.compare_digest(_b64url_encode(expected_signature), signature_segment):
        raise ValueError("invalid JWT signature")

    now = time.time()
    _validate_temporal_claim(payload_raw.get("exp"), now, clock_skew_seconds, "expired token")
    _validate_not_before(payload_raw.get("nbf"), now, clock_skew_seconds)

    if expected_issuer and payload_raw.get("iss") != expected_issuer:
        raise ValueError("unexpected token issuer")

    if expected_audience and not _audience_matches(payload_raw.get("aud"), expected_audience):
        raise ValueError("unexpected token audience")

    return payload_raw


def _validate_temporal_claim(
    claim_value: Any,
    now_epoch_seconds: float,
    clock_skew_seconds: int,
    error_message: str,
) -> None:
    if claim_value is None:
        return
    claim_epoch_seconds = _coerce_temporal_claim(claim_value)
    if now_epoch_seconds - clock_skew_seconds > claim_epoch_seconds:
        raise ValueError(error_message)


def _validate_not_before(
    claim_value: Any,
    now_epoch_seconds: float,
    clock_skew_seconds: int,
) -> None:
    if claim_value is None:
        return
    claim_epoch_seconds = _coerce_temporal_claim(claim_value)
    if now_epoch_seconds + clock_skew_seconds < claim_epoch_seconds:
        raise ValueError("token not yet valid")


def _coerce_temporal_claim(claim_value: Any) -> float:
    if isinstance(claim_value, bool) or not isinstance(claim_value, (int, float)):
        raise ValueError("temporal claim must be numeric")
    return float(claim_value)


def _audience_matches(raw_audience: Any, expected_audience: str) -> bool:
    if isinstance(raw_audience, str):
        return raw_audience == expected_audience
    if isinstance(raw_audience, (list, tuple, set, frozenset)):
        return expected_audience in {str(item) for item in raw_audience}
    return False


def _b64url_decode(value: str) -> bytes:
    padding = "=" * (-len(value) % 4)
    try:
        return base64.urlsafe_b64decode(value + padding)
    except (ValueError, binascii.Error) as exc:
        raise ValueError("invalid base64url encoding") from exc


def _b64url_encode(value: bytes) -> str:
    return base64.urlsafe_b64encode(value).rstrip(b"=").decode("ascii")
