from backend.identity.actor import ActorContext, UserRole
from backend.shared.auth.dependencies import (
    HmacJwtIdentityProvider,
    TrustedHeaderIdentityProvider,
    build_current_actor_dependency,
)


def _b64url_encode(raw: bytes) -> str:
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def _mint_hs256_jwt(payload: dict[str, object], secret: str) -> str:
    header = {"alg": "HS256", "typ": "JWT"}
    header_segment = _b64url_encode(json.dumps(header, separators=(",", ":"), sort_keys=True).encode("utf-8"))
    payload_segment = _b64url_encode(json.dumps(payload, separators=(",", ":"), sort_keys=True).encode("utf-8"))
    signing_input = f"{header_segment}.{payload_segment}".encode("ascii")
    signature = hmac.new(secret.encode("utf-8"), signing_input, hashlib.sha256).digest()
    return f"{header_segment}.{payload_segment}.{_b64url_encode(signature)}"


def _encode_claims_header(claims: dict[str, Any]) -> str:
    return _b64url_encode(json.dumps(claims, separators=(",", ":"), sort_keys=True).encode("utf-8"))


class AuditSink:
    def __init__(self) -> None:
        self.events: list[dict[str, str]] = []

    def record_state_change(self, actor: ActorContext) -> None:
        self.events.append(
            {
                "actor_user_id": str(actor.user_id),
                "request_id": actor.request_id,
                "role": actor.role.value,
            }
        )


def _build_app(identity_provider: Any) -> FastAPI:
    app = FastAPI()
    app.state.audit_sink = AuditSink()

    current_actor = build_current_actor_dependency(identity_provider)
    state_changer = build_current_actor_dependency(
        identity_provider,
        allowed_roles=(UserRole.operator, UserRole.admin),
    )

    @app.get("/protected/read")
    async def protected_read(actor: ActorContext = Depends(current_actor)) -> dict[str, str]:
        return {
            "user_id": str(actor.user_id),
            "role": actor.role.value,
            "request_id": actor.request_id,
        }

    @app.post("/protected/write")
    async def protected_write(actor: ActorContext = Depends(state_changer)) -> dict[str, str]:
        app.state.audit_sink.record_state_change(actor)
        return {
            "actor_user_id": str(actor.user_id),
            "role": actor.role.value,
            "request_id": actor.request_id,
        }

    return app


def _build_hmac_app() -> FastAPI:
    provider = HmacJwtIdentityProvider(
        shared_secret="test-secret",
        expected_issuer="https://issuer.example",
        expected_audience="docufu-api",
    )
    return _build_app(provider)


def _build_trusted_header_app() -> FastAPI:
    provider = TrustedHeaderIdentityProvider(claims_header="x-auth-claims")
    return _build_app(provider)


def _token_for(
    role: str | None,
    user_id: str,
    *,
    subject: str,
    issuer: str = "https://issuer.example",
    audience: str | list[str] = "docufu-api",
    extra_claims: dict[str, object] | None = None,
) -> str:
    now = int(time.time())
    payload: dict[str, object] = {
        "sub": subject,
        "user_id": user_id,
        "name": f"{(role or 'unknown').title()} User",
        "email": f"{(role or 'unknown')}@example.it",
        "iss": issuer,
        "aud": audience,
        "iat": now,
        "nbf": now,
        "exp": now + 600,
    }
    if role is not None:
        payload["roles"] = [role]
    if extra_claims:
        payload.update(extra_claims)
    return _mint_hs256_jwt(payload, "test-secret")


